import pyomo.environ as pyo

DATA = {
    "aircraft": [0, 1, 2],
    "pairs": [(0, 1), (0, 2), (1, 2)],
    # time windows [earliest, latest]
    "earliest": {0: 24, 1: 180, 2: 215},
    "latest":   {0: 84, 1: 240, 2: 275},
    # target landing times (earliest allowed target)
    "target":   {0: 54, 1: 210, 2: 245},
    # early penalty rates per minute
    "early_rate": {0: 21, 1: 16, 2: 49},
    # late penalty rates per minute
    "late_rate":  {0: 57, 1: 34, 2: 45},
    # separation set 1: sep1[i][j] = required gap if i lands before j
    "sep1": {
        (0, 1): 5, (1, 0): 96,
        (0, 2): 4, (2, 0): 131,
        (1, 2): 5, (2, 1): 25,
    },
    # separation set 2: sep2[i][j] = required gap if i lands before j
    "sep2": {
        (0, 1): 216, (1, 0): 2,
        (0, 2): 251, (2, 0): 1,
        (1, 2): 95, (2, 1): 3,
    },
    # big-M values per ordered pair (max possible separation window span)
    "bigM1": {
        (0, 1): 216, (1, 0): 216,
        (0, 2): 251, (2, 0): 251,
        (1, 2): 95, (2, 1): 95,
    },
    "bigM2": {
        (0, 1): 216, (1, 0): 216,
        (0, 2): 251, (2, 0): 251,
        (1, 2): 95, (2, 1): 95,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["aircraft"], ordered=True)
    model.P = pyo.Set(initialize=d["pairs"], dimen=2)

    # Decision variables
    def land_bounds(m, i):
        return (d["earliest"][i], d["latest"][i])

    model.land = pyo.Var(model.I, domain=pyo.NonNegativeReals, bounds=land_bounds)
    model.early = pyo.Var(model.I, domain=pyo.NonNegativeReals)
    model.late = pyo.Var(model.I, domain=pyo.NonNegativeReals)
    model.before = pyo.Var(model.P, domain=pyo.Binary)

    # Target timing: land = target - early + late
    def target_rule(m, i):
        return m.land[i] == d["target"][i] - m.early[i] + m.late[i]

    model.target_con = pyo.Constraint(model.I, rule=target_rule)

    # Objective: minimize total penalty
    def obj_rule(m):
        return sum(
            d["early_rate"][i] * m.early[i] + d["late_rate"][i] * m.late[i]
            for i in m.I
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Separation constraints (set 1)
    # If before[i,j] == 1: land[j] >= land[i] + sep1[i,j]
    # If before[i,j] == 0: land[i] >= land[j] + sep1[j,i]
    def sep1_forward_rule(m, i, j):
        return m.land[j] >= m.land[i] + d["sep1"][(i, j)] - d["bigM1"][(i, j)] * (
            1 - m.before[(i, j)]
        )

    model.sep1_forward = pyo.Constraint(model.P, rule=sep1_forward_rule)

    def sep1_backward_rule(m, i, j):
        return m.land[i] >= m.land[j] + d["sep1"][(j, i)] - d["bigM1"][(j, i)] * m.before[
            (i, j)
        ]

    model.sep1_backward = pyo.Constraint(model.P, rule=sep1_backward_rule)

    # Separation constraints (set 2)
    def sep2_forward_rule(m, i, j):
        return m.land[j] >= m.land[i] + d["sep2"][(i, j)] - d["bigM2"][(i, j)] * (
            1 - m.before[(i, j)]
        )

    model.sep2_forward = pyo.Constraint(model.P, rule=sep2_forward_rule)

    def sep2_backward_rule(m, i, j):
        return m.land[i] >= m.land[j] + d["sep2"][(j, i)] - d["bigM2"][(j, i)] * m.before[
            (i, j)
        ]

    model.sep2_backward = pyo.Constraint(model.P, rule=sep2_backward_rule)

    return model


